parameters.jsCode:
const item = $input.first().json;

const assignedUser = item.data?.assigned_to_user || {};

return [
    {
        json: {
            ...item,

            suite_lead_id: item.data?.id || null,
            suite_lead_uuid: item.data?.uuid || null,

            asesor_id: assignedUser.id || null,
            asesor_nombre: [
                assignedUser.first_name,
                assignedUser.last_name
            ].filter(Boolean).join(' ') || null,

            asesor_email: assignedUser.email || null,
            asesor_telefono: assignedUser.phone || null
        }
    }
];

// Rama MercadoLibre: mismo comentario que PILOT-MELI (Publicación | Precio |
// Link | Asesor | Teléfono asesor) + el resumen de la IA. Sin fila en
// meli_leads se carga igual con el origen ML, para no perder el lead.
const lead = $('When Executed by Another Workflow').first().json;
const meli = $('buscarTelefono').first().json || {};
const asesor = $input.first().json || {};

const esUsado = meli.item_condition === 'used';
const tipo = asesor.tipo || 'VN';

const datosMeli = meli.item_id
  ? `Publicación: ${meli.item_id} | Precio: ${meli.item_precio ?? ''} | Link: ${meli.item_permalink || ''} | Asesor: ${asesor.nombre || ''} | Teléfono asesor: ${meli.asesor_phone || ''}`
  : `Publicación: ${lead.meli_publicacion_id || 'no identificada'}`;

// Si la IA no sabe el modelo, el título de la publicación.
const productoIA = String(lead.ProductoInteres || '').trim();
const producto = productoIA && !/^no mencionado$/i.test(productoIA) ? productoIA : (meli.item_titulo || productoIA);

return [{
  json: {
    ...lead,
    asesor_nombre: asesor.nombre || null,
    asesor_telefono: asesor.telefono || null,
    asesor_email: asesor.email || null,
    asesor_tipo: tipo,
    hasAdvisor: Boolean(asesor.telefono),
    marca_detectada: esUsado ? 'USADOS' : 'BAIC',
    pilot_firstname: meli.buyer_nombre || lead.nombreDeclarado || lead.name || '',
    pilot_product: producto,
    pilot_notes: datosMeli + (lead.resumen ? ` | Resumen IA: ${lead.resumen}` : ''),
    pilot_origin: esUsado ? 'G84OGKG4B30WJZSW1' : 'G7UFEG023OJO3QXVK',
    pilot_business_type_id: esUsado ? 2 : (tipo === 'PDA' ? 3 : 1),
    contentVariables: JSON.stringify({
      "1": lead.nombreDeclarado || lead.name || "No definido",
      "2": lead.number || "No definido",
      "3": producto || "No definido",
      "4": asesor.boca_venta || "No definida",
      "5": "ML: " + (meli.item_permalink || "") + " | " + (lead.resumen || "No definido")
    })
  }
}];

// El bot avisa ml/meli_publicacion_id, pero los pierde si se reinicia a mitad
// de la charla. Si este teléfono tiene un lead de MercadoLibre que el bot ya
// marcó (bot_uploaded = 1) en las últimas 24 h, va por la rama ML igual:
// PILOT-MELI ya no lo va a cargar.
const lead = $('When Executed by Another Workflow').first().json;
const row = $input.first().json || {};
const esMl = lead.ml === 'si' || !!row.item_id;
return [{ json: { ...lead, ml: esMl ? 'si' : 'no', meli_publicacion_id: lead.meli_publicacion_id || row.item_id || null } }];

